function stepOpening(dt){if(openingPhase!=='walk'){openingElapsed+=dt;if(openingPhase==='confront'&&openingElapsed>1.1){openingPhase='origin';openingCard('THE WAYNES ARE ATTACKED','A robber demands the family’s money. Thomas steps between the gunman and his family. A sudden flash—and Bruce is left alone beneath the theater lights. The moment is shown without graphic detail.','CONTINUE')}return}const up=keysDown.has('w')||keysDown.has('arrowup'),down=keysDown.has('s')||keysDown.has('arrowdown'),left=keysDown.has('a')||keysDown.has('arrowleft'),right=keysDown.has('d')||keysDown.has('arrowright');let dx=(right?1:0)-(left?1:0),dz=(down?1:0)-(up?1:0),len=Math.hypot(dx,dz);if(len){dx=dx/len;dz=dz/len;youngBruce.position.x=THREE.MathUtils.clamp(youngBruce.position.x+dx*5*dt,-5,5);youngBruce.position.z=THREE.MathUtils.clamp(youngBruce.position.z+dz*5*dt,-20,16);youngBruce.rotation.y=Math.atan2(dx,dz);youngBruce.userData.walk+=dt*9;animateFigure(youngBruce,dt,true)}else animateFigure(youngBruce,dt,false);const z=youngBruce.position.z;thomasWayne.position.lerp(new THREE.Vector3(youngBruce.position.x-1.3,0,z+1.5),Math.min(1,dt*4));marthaWayne.position.lerp(new THREE.Vector3(youngBruce.position.x+1.3,0,z+1.5),Math.min(1,dt*4));for(const g of [thomasWayne,marthaWayne]){g.rotation.y=Math.PI;animateFigure(g,dt,len>0)}if(z< -18.5){openingPhase='confront';openingElapsed=0;keysDown.clear();gunman.position.set(1.4,0,-20);gunman.rotation.y=-.3;thomasWayne.position.set(-.8,0,-18);thomasWayne.rotation.y=Math.PI;marthaWayne.position.set(1.1,0,-18);marthaWayne.rotation.y=Math.PI;youngBruce.rotation.y=Math.PI;}}
