let mode='story',gameStarted=false,paused=false,dialogueLock=false,queue=[],afterTalk=null,storyStage=0,gangDown=0,clues=0,riddleSolved=0,currentRiddle=null,detective=false,combo=0,comboTimer=0,boss=null,selected=0,health=100,heroHealth=100,stealth=false,glide=false,ride=null,toastTimer=0,attackTimer=0,damageTimer=0,gameTime=0,cameraYaw=0,cameraPitch=.2,mouse=null,keys={},target=null,clock=new THREE.Clock();
