function updateObjective(){if(mode==='villain'){setObjective('Defeat Batman and Robin. Swap villains with Q.','VILLAIN RAMPAGE · '+villains[selected],100-heroHealth,100,`HERO VITALS ${heroHealth}%`);return}if(storyStage===0)setObjective(`Stop the gang operation. ${Math.max(0,5-gangDown)} crew members remain.`,'THE STREET WAR',gangDown,5,`${gangDown} / 5 crew stopped`);if(storyStage===1)setObjective('Search Gotham for the Riddler’s evidence. Look for cyan glows.','A TRAIL OF RIDDLES',clues,8,`${clues} / 8 key clues · ${challengeCount()} / 50 challenges`);if(storyStage===2)setObjective('Confront the Riddler at his hideout. Watch his tells.','THE RIDDLER',boss?.health??100,100,`RIDDLER · ${Math.ceil(boss?.health??100)}%`);if(storyStage===3)setObjective('Face Harvey Dent before the city loses him completely.','THE DARK SIDE OF JUSTICE',boss?.health??100,100,`TWO-FACE · ${Math.ceil(boss?.health??100)}%`);if(storyStage>=4)setObjective('Gotham is safe tonight. The case is yours to replay.','CASE FILE CLOSED',1,1,'CITY STATUS: HOLDING')}
