function leaveVehicle(){if(!ride)return;const v=ride,side=new THREE.Vector3(Math.cos(v.rotation.y),0,-Math.sin(v.rotation.y));ride=null;vehicleSpeed=0;player.visible=true;player.position.copy(v.position).addScaledVector(side,2.2);player.position.y=0;if(blocked(player.position.x,player.position.z))player.position.copy(v.position).add(new THREE.Vector3(0,0,-2.5));toast('EXITED '+(v===batmobile?'BATMOBILE':'ROBIN MOTORCYCLE'));sfx(230,.13);updateGadgetHud()}
function enterVehicle(v){const expected=player===bat?batmobile:bike;if(v!==expected){toast(player===bat?'ROBIN HAS HIS OWN MOTORCYCLE':'BATMAN HAS HIS OWN VEHICLE');return}ride=v;player.visible=false;vehicleSpeed=0;toast(v===batmobile?'BATMOBILE · ENGINE ONLINE':'ROBIN MOTORCYCLE · ENGINE ONLINE');sfx(90,.25,'sawtooth');updateGadgetHud()}
