function selectGrapplePoint(){const p=player.position,dir=forward();let best=null,score=Infinity;for(const point of rooftopPoints){const dx=point.position.x-p.x,dz=point.position.z-p.z,d=Math.hypot(dx,dz),dot=d?(dx*dir.x+dz*dir.z)/d:1;if(d>4&&d<42&&dot>.12){const s=d-dot*8;if(s<score){score=s;best=point}}}grappleTarget=best;for(const point of rooftopPoints)point.mesh.visible=point===best;$('#target-reticle').classList.toggle('hidden',!best||grappleTime>0);return best}
function useGrapple(){if(ride||grappleTime>0||grappleCooldown>0)return;const point=selectGrapplePoint();if(!point){toast('NO ROOFTOP GRAPPLE POINT IN RANGE');return}grapplePoint=new THREE.Vector3(point.position.x,Math.max(0,point.position.y-1.7),point.position.z);grappleTime=1.05;grappleCooldown=1.25;glide=false;if(!grappleRope){grappleRope=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:0xcbd6de}));scene.add(grappleRope)}grappleRope.visible=true;sfx(760,.18,'triangle');toast('GRAPPLE LOCK · PULLING TO ROOFTOP')}
function toggleGlide(){if(ride)return;if(!glide){if(player.position.y<.1)verticalVelocity=7.6;glide=true;sfx(280,.1,'sine');toast(player===bat?'CAPE GLIDE · STEER WITH WASD':'ROBIN WINGS · STEER WITH WASD')}else{glide=false;sfx(180,.1,'sine');toast('GLIDE FOLDED')}}
function jump(){if(ride)return;if(player.position.y<=.05){verticalVelocity=8;glide=false;sfx(360,.08);}}
function cycleGadget(){gadgetIndex=(gadgetIndex+1)%2;updateGadgetHud();toast((player===bat?'BATMAN · ':'ROBIN · ')+(player===bat?gadgets[gadgetIndex]:gadgetIndex?'WINGS':'ROBIN WINGS').toUpperCase())}
function updateGadgetHud(){const batman=player===bat,name=batman?gadgets[gadgetIndex]:(gadgetIndex?'Robin Wings':'Robin Wings');$('#gadget-owner').textContent=batman?'BATMAN · GADGET':'ROBIN · EQUIPMENT';$('#gadget-name').textContent=name.toUpperCase();$('#gadget-icon').textContent=gadgetIndex?'◉':'✦';$('#gadget-status').textContent=gadgetCooldown>0?`COOLDOWN ${gadgetCooldown.toFixed(1)}s`:`READY · T SELECT`;$('#gadget-hud').classList.toggle('vehicle-ready',!!ride)}
function throwGadget(){if(ride||gadgetCooldown>0)return;const isSmoke=player===bat&&gadgetIndex===1;if(isSmoke){gadgetCooldown=5.5;const cloud=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),new THREE.MeshBasicMaterial({color:0x9caab4,transparent:true,opacity:.32,depthWrite:false}));cloud.scale.set(1.7,1.1,1.7);cloud.position.copy(player.position).add(new THREE.Vector3(0,1,0));scene.add(cloud);smokeClouds.push({mesh:cloud,time:3});const dir=forward();player.position.x-=dir.x*1.6;player.position.z-=dir.z*1.6;stealthTimer=2.6;setStealth(true);sfx(190,.32,'triangle');toast('SMOKE PELLET · VANISH AND REPOSITION');updateGadgetHud();return}gadgetCooldown=1.1;attackCooldown=.35;const arm=player.userData.r;if(arm)arm.rotation.x=-1.4;const projectile=new THREE.Group(),disc=new THREE.Mesh(new THREE.TorusGeometry(.24,.055,6,12),new THREE.MeshStandardMaterial({color:player===bat?0xb7c2ce:0xe9bd58,metalness:.65,emissive:player===bat?0x172b38:0x4c2417}));disc.rotation.x=Math.PI/2;projectile.add(disc);projectile.position.copy(player.position).add(new THREE.Vector3(0,1.55,0));const d=forward();projectile.userData={velocity:new THREE.Vector3(d.x*23,1,d.z*23),life:2.2,disc,owner:player,returning:false,hit:false};scene.add(projectile);projectiles.push(projectile);sfx(player===bat?600:520,.16,'triangle');toast(player===bat?'BATARANG THROWN':'ROBIN WINGS THROWN');updateGadgetHud()}
function rideAction(){if(ride){leaveVehicle();return}const v=nearbyRide(5),expected=player===bat?batmobile:bike;if(v){enterVehicle(v);return}expected.visible=true;const dir=forward();expected.position.set(THREE.MathUtils.clamp(player.position.x+dir.x*3,-115,115),0,THREE.MathUtils.clamp(player.position.z+dir.z*3,-115,115));toast('VEHICLE SUMMONED · APPROACH AND PRESS R');sfx(120,.4,'sawtooth')}
function grappleVehicle(){if(ride){const v=ride;ride=null;vehicleSpeed=0;player.visible=true;player.position.copy(v.position).add(new THREE.Vector3(2,0,0));toast('EXITED '+(v===batmobile?'BATMOBILE':'ROBIN MOTORCYCLE'));sfx(230,.13);return}const expected=player===bat?batmobile:bike;let v=nearbyRide(5);if(!v){expected.visible=true;const dir=forward();expected.position.set(THREE.MathUtils.clamp(player.position.x+dir.x*4,-115,115),0,THREE.MathUtils.clamp(player.position.z+dir.z*4,-115,115));toast('VEHICLE SUMMONED · APPROACH AND PRESS F');sfx(120,.4,'sawtooth');return}if(v!==expected){toast(player===bat?'ROBIN HAS HIS OWN MOTORCYCLE':'BATMAN HAS HIS OWN VEHICLE');return}ride=v;player.visible=false;vehicleSpeed=0;toast(v===batmobile?'BATMOBILE · ENGINE ONLINE':'ROBIN MOTORCYCLE · ENGINE ONLINE');sfx(90,.25,'sawtooth')}
function stepGadgets(dt){gadgetCooldown=Math.max(0,gadgetCooldown-dt);grappleCooldown=Math.max(0,grappleCooldown-dt);if(stealthTimer>0){stealthTimer=Math.max(0,stealthTimer-dt);if(stealthTimer===0&&!keysDown.has('shift'))setStealth(false)}if(grappleTime>0){const t=Math.min(1,dt/Math.max(grappleTime,.001));player.position.lerp(grapplePoint,t);grappleTime=Math.max(0,grappleTime-dt);if(grappleRope){grappleRope.geometry.dispose();grappleRope.geometry=new THREE.BufferGeometry().setFromPoints([player.position.clone().add(new THREE.Vector3(0,1.3,0)),grapplePoint])}if(grappleTime===0){player.position.copy(grapplePoint);if(grappleRope)grappleRope.visible=false;for(const p of rooftopPoints)p.mesh.visible=false}}for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i],u=p.userData;u.life-=dt;if(!u.returning&&u.life<1.55)u.returning=true;if(u.returning){const destination=u.owner.position.clone().add(new THREE.Vector3(0,1.4,0)),delta=destination.sub(p.position);if(delta.length()<1||u.life<=0){scene.remove(p);projectiles.splice(i,1);continue}u.velocity.lerp(delta.normalize().multiplyScalar(27),Math.min(1,dt*5))}p.position.addScaledVector(u.velocity,dt);p.rotation.z+=dt*13;if(!u.hit&&!u.returning){const targets=mode==='villain'?villainTargets.filter(a=>a.alive):[...enemies.filter(a=>a.alive),...(boss?.alive&&mode==='story'&&storyStage>=2?[boss]:[])];const victim=targets.find(a=>Math.hypot(a.mesh.position.x-p.position.x,a.mesh.position.z-p.position.z)<1.25&&Math.abs(a.mesh.position.y+1-p.position.y)<2);if(victim){u.hit=true;u.returning=true;victim.health-=victim===boss?18:35;victim.alert=true;toast(`${u.owner===bat?'BATARANG':'WING DISC'} HIT · ${victim.name}`);if(victim.health<=0){victim.health=0;victim.alive=false;victim.mesh.visible=false;if(victim.type==='enemy'){gangDown++;progress()}if(mode==='villain'&&villainTargets.every(a=>!a.alive)){heroHealth=0;setHealth();finishVillainMode()}if(victim===boss)progress()}else if(victim===boss){$('#boss-fill').style.width=`${victim.health}%`;updateObjective()}}}if(p.position.y<-.5||p.position.length()>180){scene.remove(p);projectiles.splice(i,1)}}for(let i=smokeClouds.length-1;i>=0;i--){const cloud=smokeClouds[i];cloud.time-=dt;cloud.mesh.material.opacity=Math.max(0,.32*cloud.time/3);cloud.mesh.scale.multiplyScalar(1+dt*.16);if(cloud.time<=0){scene.remove(cloud.mesh);cloud.mesh.geometry.dispose();smokeClouds.splice(i,1)}}updateGadgetHud()}
function setStealth(on){stealth=on;player.traverse(o=>{if(o.isMesh&&o.material?.emissive)o.material.emissive.setHex(on?0x101c27:0x000000)})}
function highlight(root,color,on){root.traverse(o=>{if(!o.isMesh)return;if(on){if(!o.userData.detectiveMaterial)o.userData.detectiveMaterial=o.material;o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone();if(o.material.emissive){o.material.emissive.setHex(color);o.material.emissiveIntensity=2.2}}else if(o.userData.detectiveMaterial){o.material=o.userData.detectiveMaterial;delete o.userData.detectiveMaterial}})}
function setDetective(on){if(on&&(player!==bat||mode!=='story')){toast('DETECTIVE MODE IS FOR BATMAN ONLY');return}detective=on;$('#detective-overlay').classList.toggle('hidden',!on);for(const e of evidence)highlight(e.mesh,0x24d9ef,on);for(const r of riddles)highlight(r.mesh,0x80ff70,on);for(const a of [...enemies,...actors.filter(a=>a.type==='villain')])highlight(a.mesh,0xff3d42,on&&a.alive&&a.mesh.visible);toast(on?'DETECTIVE VISION ACTIVE':'DETECTIVE VISION OFF')}
function doAction(a){if(a==='attack')strike();if(a==='interact')interact();if(a==='swap')swap();if(a==='stealth')setStealth(!stealth);if(a==='glide')toggleGlide();if(a==='jump')jump();if(a==='gadget')throwGadget();if(a==='cycle')cycleGadget();if(a==='vehicle')rideAction();if(a==='grapple')useGrapple();if(a==='detective')setDetective(!detective)}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(currentRiddle){if(['1','2','3'].includes(k))answerRiddle(Number(k)-1);if(k==='escape'&&!e.repeat){$('#riddle-card').classList.add('hidden');currentRiddle=null}return}if(dialogueLock&&(k==='enter'||k===' ')){if(!e.repeat)showLine();return}keysDown.add(k);if(k==='q'&&!e.repeat)swap();if(k==='e'&&!e.repeat)interact();if(k===' '&&!e.repeat)jump();if(k==='f'&&!e.repeat)useGrapple();if(k==='g'&&!e.repeat)toggleGlide();if(k==='t'&&!e.repeat)cycleGadget();if(k==='r'&&!e.repeat)rideAction();if(k==='x'&&!e.repeat)throwGadget();if(k==='v'&&!e.repeat)setDetective(!detective);if(k==='shift')setStealth(true);if(k==='escape'&&!e.repeat){if(garageOpen)closeGarage();else pause()}});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keysDown.delete(k);if(k==='shift')setStealth(false)});
canvas.addEventListener('pointerdown',e=>{if(!gameStarted||paused)return;if(e.pointerType==='touch'){if(e.clientX>innerWidth*.45){mobileLook={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture?.(e.pointerId)}return}pointerDown={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',e=>{if(mobileLook?.id===e.pointerId){mobileLook=null;return}if(e.pointerType!=='touch'&&pointerDown&&Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)<8)strike();pointerDown=null});canvas.addEventListener('pointercancel',e=>{if(mobileLook?.id===e.pointerId)mobileLook=null;pointerDown=null});canvas.addEventListener('pointermove',e=>{const drag=mobileLook?.id===e.pointerId?mobileLook:pointerDown?.id===e.pointerId?pointerDown:null;if(drag){cameraYaw-=(e.clientX-drag.x)*.006;cameraPitch=THREE.MathUtils.clamp(cameraPitch+(e.clientY-drag.y)*.003,-.1,.75);drag.x=e.clientX;drag.y=e.clientY}});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keysDown.add(k);b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keysDown.delete(k))});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();doAction(b.dataset.action)}));

function pollGamepad(dt){const pad=navigator.getGamepads?.()[0];if(!pad)return;const dead=.22,axes=[pad.axes[0]||0,pad.axes[1]||0],mapped=['gp-left','gp-right','gp-up','gp-down'];mapped.forEach(k=>keysDown.delete(k));if(axes[0]<-dead)keysDown.add('gp-left');if(axes[0]>dead)keysDown.add('gp-right');if(axes[1]<-dead)keysDown.add('gp-up');if(axes[1]>dead)keysDown.add('gp-down');const lookX=pad.axes[2]||0,lookY=pad.axes[3]||0;if(Math.abs(lookX)>dead)cameraYaw-=lookX*dt*2.7;if(Math.abs(lookY)>dead)cameraPitch=THREE.MathUtils.clamp(cameraPitch+lookY*dt*1.7,-.1,.75);const actions={0:'attack',1:'jump',2:'gadget',3:'interact',4:'swap',5:'grapple',6:'glide',7:'vehicle',8:'cycle',9:'pause'},now=new Set();for(const [id,action]of Object.entries(actions))if(pad.buttons[Number(id)]?.pressed){now.add(action);if(!gamepadLast.has(action)){if(action==='pause')pause();else doAction(action)}}gamepadLast=now}
window.addEventListener('gamepadconnected',()=>toast('CONTROLLER CONNECTED · LEFT STICK MOVE · FACE BUTTONS ACTIONS'));
function updateInteraction(){let text='';if(!ride&&Math.hypot(player.position.x-garage.position.x,player.position.z-garage.position.z)<4.5)text='[ E ]  OPEN WAYNE CAVE GARAGE';else if(!ride&&riddles.some(r=>!r.solved&&Math.hypot(player.position.x-r.mesh.position.x,player.position.z-r.mesh.position.z)<3))text='[ E ]  SOLVE RIDDLE';else if(ride)text='[ E ]  EXIT VEHICLE';else if(nearbyRide(4))text='[ E ]  ENTER VEHICLE';else if(nearestActor(3.2))text='[ E ]  TALK';else if(evidence.some(e=>!e.found&&Math.hypot(player.position.x-e.mesh.position.x,player.position.z-e.mesh.position.z)<2))text='[ E ]  COLLECT CHALLENGE';$('#interaction').textContent=text;$('#interaction').classList.toggle('show',!!text)}
function cameraUpdate(dt){if(introActive){const focus=youngBruce.position,dist=9.5;const desired=new THREE.Vector3(focus.x-Math.sin(cameraYaw)*dist,focus.y+3+cameraPitch*5,focus.z-Math.cos(cameraYaw)*dist);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(focus.x,focus.y+1.15,focus.z-2.5);return}const focus=ride?ride.position:player.position;const dist=ride?13:9.5;const desired=new THREE.Vector3(focus.x-Math.sin(cameraYaw)*dist,focus.y+3+cameraPitch*5,focus.z-Math.cos(cameraYaw)*dist);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(focus.x,focus.y+1.25,focus.z+1);}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock3.getDelta(),.04);if(gameStarted&&!paused){gameTime+=dt;pollGamepad(dt);stepGadgets(dt);if(introActive){stepOpening(dt)}else if(!dialogueLock&&!currentRiddle){move(dt);moveCompanion(dt);moveAlfred(dt);enemiesThink(dt);collect();updateInteraction();attackCooldown=Math.max(0,attackCooldown-dt);damageTimer=Math.max(0,damageTimer-dt);if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){combo=0;$('#combo').classList.remove('show')}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}for(const e of evidence)if(!e.found){e.mesh.rotation.y+=dt*.7;e.mesh.position.y=.12+Math.sin(gameTime*2+e.id)*.12}for(const m of markers){m.mesh.rotation.y+=dt*.35;m.mesh.visible=m.active||m.name==='GANG DISTRICT'&&storyStage===0}}animateWorldFigures(dt)}cameraUpdate(dt);showBoss();renderer.render(activeScene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.6))});
activate('GANG DISTRICT');setHealth();updateObjective();animate();
